import { asset_sub_category } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    categoriessubdeletion: Boolean,
    categoriesItem: Object
  },
  data() {
    return {
      loading: false
    };
  },
  watch: {
    categoriessubdeletion: {
      async handler() {},
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    async delete_mutation() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(asset_sub_category, {
          input: {
            user_email_id: data.user.user_email_id,
            action_type: "DELETE_SUBCATEGORY",
            sub_category_id: this.categoriesItem.sub_category_id
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.asset_sub_category);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    }
  }
};
